const app=document.querySelector('#app');
const loading=document.querySelector('#loading');
const nav=document.querySelector('#nav');
const toastEl=document.querySelector('#toast');
const localKey='babel.local.topics.v2';
const mediaKey='babel.local.media.v1';
const globalMediaKey='babel.media.room.v1';
const themeKey='babel.theme.v1';
const state={curated:[],recent:[],current:null,persistence:'browser',stats:null,piDigits:null,graph:null};
const shelves=[
  ['Physics','Relativity, spacetime, quantum theory, black holes, causality and speculative frontiers.','time-travel'],
  ['Mind','Memory, learning, hypnosis, dreams, meditation, attention and visualization.','method-of-loci'],
  ['Skills','Programming, martial arts, research practice, building, movement and other trainable systems.','coding'],
  ['Mathematics','Numbers, proof, dimensions, fractals, patterns and interactive mathematical spaces.','pi'],
  ['Traditions','Historical and esoteric traditions kept visibly separate from established scientific claims.','alchemy'],
  ['Research','Source finding, evidence classification, criticism, comparison and uncertainty.','research-methods'],
  ['Computing','Languages, algorithms, web systems, tools and projects.','javascript'],
  ['Babel','The internal Library, Network, Pi index, generated images and architecture of this project.','library-of-babel']
];
const evidenceNotes={
  established:'Strongly supported or formally established in its field.',
  theoretical:'Unverified, disputed, speculative, or theoretical material. Inspect the specific evidence and claim type.',
  historical:'Documented historical material or tradition. Historical existence does not validate every associated claim.',
  practical:'A learnable skill domain where competent instruction and practice matter.',
  mixed:'Different claims within the topic have different levels of support.',
  open:'An index entry awaiting deeper sourcing and classification.'
};
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function slug(s){return String(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'untitled'}
function titleFromSlug(s){return String(s||'').replace(/-/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
function hash32(input){let h=2166136261>>>0;for(let i=0;i<String(input).length;i++){h^=String(input).charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function hashHex(s){return hash32(s).toString(16).padStart(8,'0')}
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function localTopics(){try{return JSON.parse(localStorage.getItem(localKey)||'{}')}catch{return {}}}
function saveLocal(topic){const all=localTopics();all[topic.slug]=topic;localStorage.setItem(localKey,JSON.stringify(all))}
function mediaMap(){try{return JSON.parse(localStorage.getItem(mediaKey)||'{}')}catch{return {}}}
function saveTopicMedia(topicSlug,item){const all=mediaMap();all[topicSlug]=all[topicSlug]||[];all[topicSlug].unshift(item);all[topicSlug]=all[topicSlug].slice(0,24);localStorage.setItem(mediaKey,JSON.stringify(all))}
function roomMedia(){try{return JSON.parse(localStorage.getItem(globalMediaKey)||'[]')}catch{return []}}
function saveRoomMedia(item){const arr=roomMedia();arr.unshift(item);localStorage.setItem(globalMediaKey,JSON.stringify(arr.slice(0,40)))}
function start(){loading.classList.remove('hidden')}function stop(){loading.classList.add('hidden')}
function setTitle(t){document.title=t?`${t} · Website Of Babel`:'Website Of Babel'}
function toast(msg){toastEl.textContent=msg;toastEl.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>toastEl.classList.remove('show'),1800)}
function route(path,{replace=false}={}){if(replace)history.replaceState({},'',path);else history.pushState({},'',path);nav.classList.remove('open');renderRoute()}
function fmtDate(s){try{return new Intl.DateTimeFormat(undefined,{year:'numeric',month:'short',day:'numeric'}).format(new Date(s))}catch{return 'today'}}
async function json(url,opts){const r=await fetch(url,opts);const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d}
async function loadExplore(){if(state.curated.length)return;try{const d=await json('/api/explore');state.curated=d.curated||[];state.recent=d.recent||[];state.persistence=d.persistence||'browser'}catch{state.curated=[];state.recent=[]}}
async function loadStats(){try{state.stats=await json('/api/stats');document.querySelector('#indexNumber').textContent=`INDEX ${String((state.stats.curated||0)+(state.stats.created||0)).padStart(6,'0')}`}catch{}}
function allTopics(){const map=new Map();[...state.curated,...state.recent,...Object.values(localTopics())].forEach(t=>t&&map.set(t.slug,t));return [...map.values()]}
function evidenceClass(e=''){const x=e.toLowerCase();if(/not established|unverified|unsupported|disputed|paranormal claim|speculat/.test(x))return 'theoretical';if(/historical|traditional|esoteric|cultural|religious|theological|folklore|literary/.test(x))return 'historical';if(/mixed|varies|source dependent/.test(x))return 'mixed';if(/practical/.test(x))return 'practical';if(/established|well-supported|mathematical|documented phenomenon/.test(x))return 'established';return 'open'}
function evidenceBlurb(e){return evidenceNotes[evidenceClass(e)]}
function applyTheme(theme){const actual=theme==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.documentElement.dataset.theme=actual;document.querySelector('meta[name="theme-color"]').content=actual==='dark'?'#111310':'#f2efe7';document.querySelector('#themeIcon').textContent=actual==='dark'?'☀':'◐'}
function initTheme(){const saved=localStorage.getItem(themeKey)||'auto';applyTheme(saved);document.querySelector('#themeToggle').onclick=()=>{const dark=document.documentElement.dataset.theme==='dark';const next=dark?'light':'dark';localStorage.setItem(themeKey,next);applyTheme(next);if(location.pathname==='/network')renderRoute();if(location.pathname==='/pi'&&state.piDigits)setTimeout(drawPiCanvas,30)}}
function wireRoutes(){document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||a.target==='_blank')return;e.preventDefault();const u=new URL(a.href,location.origin);route(u.pathname+u.search)})}
function topicVisual(title){const c=esc((title||'B')[0].toUpperCase());return `<div class="topic-poster"><div class="orb"></div><div class="letter">${c}</div></div>`}
function home(){setTitle('');const localCount=Object.keys(localTopics()).length;app.innerHTML=`<div class="page">
<section class="home-hero"><div><div class="kicker">The everything website · self-expanding index</div><h1 class="hero-title">One entrance to <em>anything.</em></h1></div><p class="hero-copy">Search a subject, open a generated space, follow its connections, or build a new branch. Babel is designed as a durable index rather than a disposable answer stream.<small>Scientific claims, traditions, speculation, practical skills, and generated systems are labeled instead of being flattened into one kind of truth.</small></p></section>
<form class="search-wrap" id="homeSearch"><input id="homeQ" aria-label="Search Babel" autocomplete="off" placeholder="What do you want to know?" maxlength="180"><button>Enter Babel</button></form><div class="search-state" id="searchState">Search anything or enter one of the three core Babel systems.</div><div class="suggestions">${['time travel','method of loci','hypnosis','black holes','boxing','python','fractals'].map(x=>`<button type="button" data-query="${esc(x)}">${esc(x)}</button>`).join('')}</div>
<div class="index-strip"><div class="stat"><strong>${state.stats?.curated??28}</strong><span>Curated foundations</span></div><div class="stat"><strong>${state.stats?.created??0}</strong><span>Shared entries</span></div><div class="stat"><strong>${localCount}</strong><span>Local branches</span></div><div class="stat"><strong>100K</strong><span>Indexed Pi digits</span></div></div>
<div class="section-row"><div><div class="kicker">Core systems</div><h2>Babel inside Babel.</h2></div><p>These are not links to somebody else's project. They are built into this site and share the same index, routing, theme, and knowledge graph.</p></div>
<div class="engine-grid"><article class="engine-card" data-go="/network"><div class="number">SYSTEM 01 / GRAPH</div><h3>Network<br>of Babel</h3><p>Navigate the live knowledge graph, inspect relationships, search nodes, pan, zoom, and jump directly into entries.</p><span class="arrow">↗</span><div class="engine-art"></div></article><article class="engine-card" data-go="/library"><div class="number">SYSTEM 02 / GENERATIVE LIBRARY</div><h3>Library<br>of Babel</h3><p>Deterministic addresses map to repeatable books and pages. Locate phrases, browse shelves, copy coordinates, and return to the same page later.</p><span class="arrow">↗</span><div class="engine-art"></div></article><article class="engine-card" data-go="/pi"><div class="number">SYSTEM 03 / NUMBER ARCHIVE</div><h3>Pi<br>of Babel</h3><p>Search the first 1,000,000 audited digits of pi, inspect exact hits and positions, verify the corpus hash, compare frequencies, and visualize the digit field.</p><span class="arrow">↗</span><div class="engine-art"></div></article></div>
<div class="section-row"><div><div class="kicker">Index</div><h2>Start with a shelf.</h2></div><a class="section-link" href="/explore" data-route>Open full index →</a></div><div class="shelf-grid">${shelves.map((x,i)=>`<article class="shelf-card" data-open="${esc(x[2])}"><div class="shelf-number">${String(i+1).padStart(2,'0')}</div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><span class="arrow">↗</span></article>`).join('')}</div>
<div class="section-row"><div><div class="kicker">More than text</div><h2>Read, map, calculate, generate.</h2></div><p>Babel entries can carry images and video, while dedicated rooms handle deterministic images, numeric exploration, generated books, learning structures, and source paths.</p></div><div class="feature-grid"><article class="feature-card" data-go="/media"><div class="kicker">Media room</div><h3>Images and video belong beside the knowledge.</h3><p>Generate deterministic images from seeds, preview image or video URLs, save a personal media shelf, and attach media to topic pages.</p><div class="feature-visual"></div></article><article class="feature-card" data-go="/workbench"><div class="kicker">Workbench</div><h3>Turn an entry into practice.</h3><p>Lessons, memory routes, timelines, project briefs, research questions, and comparison structures.</p><div class="feature-visual"></div></article><article class="feature-card" data-open="research-methods"><div class="kicker">Evidence</div><h3>Keep uncertainty visible.</h3><p>Every entry has an evidence label and source desk so speculation does not quietly become fact.</p><div class="feature-visual"></div></article></div>
</div>`;
wireSearch('#homeSearch','#homeQ','#searchState');document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>openTopic(b.dataset.query));document.querySelectorAll('[data-open]').forEach(e=>e.onclick=()=>openTopic(e.dataset.open));document.querySelectorAll('[data-go]').forEach(e=>e.onclick=()=>route(e.dataset.go));wireRoutes()}
function wireSearch(formSel,inputSel,statusSel){const form=document.querySelector(formSel);if(!form)return;form.onsubmit=async e=>{e.preventDefault();const input=document.querySelector(inputSel);const status=document.querySelector(statusSel);const q=input.value.trim();if(!q)return;if(status)status.textContent=`Opening index for “${q}”...`;await openTopic(q)}}
async function openTopic(q){start();try{const s=slug(q);const local=localTopics()[s];if(local){state.current=local;route(`/topic/${s}`);return}const d=await json(`/api/topic?q=${encodeURIComponent(q)}`);state.current=d.topic;state.persistence=d.persistence||'browser';if(d.persistence!=='shared')saveLocal(d.topic);route(`/topic/${d.topic.slug}`)}catch(err){const st=document.querySelector('#searchState');if(st){st.textContent=err.message;st.classList.add('error')}else toast(err.message)}finally{stop()}}
async function explore(){setTitle('Explore');await loadExplore();const topics=allTopics();const cats=['All',...new Set(topics.map(t=>t.category).filter(Boolean))];app.innerHTML=`<div class="page"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">Index room</div><h1>Explore</h1></div><p>Browse curated foundations and user-created branches. Search demand can add new entries, while the index keeps their addresses stable.</p></div></header><div class="filter-bar"><input class="network-search" id="exploreSearch" placeholder="Filter entries"><div id="catFilters">${cats.map((c,i)=>`<button class="chip ${i===0?'active':''}" data-cat="${esc(c)}">${esc(c)}</button>`).join('')}</div></div><div class="topic-grid" id="topicGrid"></div></div>`;
let cat='All',q='';const draw=()=>{const filtered=topics.filter(t=>(cat==='All'||t.category===cat)&&(!q||`${t.title} ${t.dek||''} ${(t.tags||[]).join(' ')}`.toLowerCase().includes(q)));document.querySelector('#topicGrid').innerHTML=filtered.length?filtered.map(t=>`<article class="topic-card" data-topic="${esc(t.slug)}"><div class="meta">${esc(t.category||'General')} · ${esc(t.kind||'index')}</div><h3>${esc(t.title)}</h3><p>${esc(t.dek||'Babel index entry.')}</p><div class="tags">${(t.tags||[]).slice(0,4).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div></article>`).join(''):`<div class="empty">No entries match this filter.</div>`;document.querySelectorAll('[data-topic]').forEach(e=>e.onclick=()=>openTopic(e.dataset.topic))};draw();document.querySelector('#exploreSearch').oninput=e=>{q=e.target.value.trim().toLowerCase();draw()};document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{cat=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));draw()})}
function mediaType(url,type){if(type&&type!=='auto')return type;const u=String(url||'').toLowerCase();if(/youtube\.com|youtu\.be/.test(u))return'youtube';if(/vimeo\.com/.test(u))return'vimeo';if(/\.(mp4|webm|ogg)(\?|$)/.test(u))return'video';return'image'}
function youtubeId(url){try{const u=new URL(url);if(u.hostname.includes('youtu.be'))return u.pathname.split('/').filter(Boolean)[0]||'';if(u.searchParams.get('v'))return u.searchParams.get('v');const m=u.pathname.match(/\/embed\/([^/]+)/);return m?m[1]:''}catch{return''}}
function vimeoId(url){const m=String(url).match(/vimeo\.com\/(?:video\/)?(\d+)/);return m?m[1]:''}
function mediaHTML(item){const url=esc(item.url||'');const type=mediaType(item.url,item.type);let body='';if(type==='youtube'){const id=youtubeId(item.url);body=id?`<iframe src="https://www.youtube-nocookie.com/embed/${esc(id)}" title="${esc(item.caption||'Video')}" loading="lazy" allow="accelerometer; autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`:'<div class="muted">Invalid YouTube URL</div>'}else if(type==='vimeo'){const id=vimeoId(item.url);body=id?`<iframe src="https://player.vimeo.com/video/${esc(id)}" title="${esc(item.caption||'Video')}" loading="lazy" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>`:'<div class="muted">Invalid Vimeo URL</div>'}else if(type==='video'){body=`<video controls preload="metadata" src="${url}"></video>`}else{body=`<img src="${url}" alt="${esc(item.caption||'Topic image')}" loading="lazy" referrerpolicy="no-referrer">`}return `<div class="media-item"><div class="media-frame">${body}</div><div class="media-caption"><strong>${esc(item.caption||titleFromSlug(type))}</strong>${esc(item.note||'')}</div></div>`}
async function topicPage(s){start();let topic=state.current?.slug===s?state.current:null;const local=localTopics()[s];if(!topic&&local)topic=local;if(!topic){try{const d=await json(`/api/topic?slug=${encodeURIComponent(s)}`);topic=d.topic;state.persistence=d.persistence||'browser';if(d.persistence!=='shared')saveLocal(topic)}catch{topic=null}}stop();if(!topic){app.innerHTML='<div class="page"><div class="empty">This entry could not be opened.</div></div>';return}state.current=topic;setTitle(topic.title);const sources=topic.sources||[];const localMedia=mediaMap()[topic.slug]||[];const allMedia=[...(topic.media||[]),...localMedia];app.innerHTML=`<div class="page"><section class="topic-hero"><div class="topic-hero-grid"><div><div class="kicker">${esc(topic.category||'General')} · ${topic.kind==='curated'?'curated foundation':'created branch'}</div><h1 class="topic-title">${esc(topic.title)}</h1><p class="topic-dek">${esc(topic.dek||'A connected Babel entry.')}</p></div>${topicVisual(topic.title)}</div></section><div class="topic-layout">
<aside class="topic-side"><div class="side-title">On this page</div><div class="side-list">${(topic.sections||[]).map((x,i)=>`<a href="#section-${i}">${esc(x.title)}</a>`).join('')}<a href="#media">Images & video</a><a href="#sources">Reference desk</a></div><div style="height:24px"></div><div class="side-title">Entry</div><div class="topic-meta"><strong>${esc(topic.id||hashHex(topic.slug))}</strong><br>${esc(topic.category||'General')}<br>${topic.createdAt?`Created ${esc(fmtDate(topic.createdAt))}<br>`:''}${topic.updated?`Updated ${esc(topic.updated)}<br>`:''}${state.persistence==='shared'?'Shared index':'Browser index'}</div></aside>
<article><div class="label-row"><span class="evidence-label"><i></i>${esc(topic.evidence||'Open research')}</span>${(topic.tags||[]).slice(0,5).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="banner ${state.persistence==='shared'?'shared':''}"><b>Evidence note:</b> ${esc(evidenceBlurb(topic.evidence||''))}</div>${(topic.sections||[]).map((sec,i)=>`<section class="topic-section" id="section-${i}"><h2>${esc(sec.title)}</h2><p>${esc(sec.body||'')}</p>${sec.points?.length?`<ul>${sec.points.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</section>`).join('')}
<section class="topic-section" id="media"><div class="kicker">Media layer</div><h2>Images & video</h2><p>Media is kept beside the entry instead of replacing the evidence layer. Personal media additions are saved in this browser.</p><div class="media-shelf" id="topicMedia">${allMedia.length?allMedia.map(mediaHTML).join(''):'<div class="banner">No media has been attached to this entry yet.</div>'}</div><div class="media-add"><div class="form-grid"><div class="field"><label>Type</label><select id="mediaType"><option value="auto">Auto detect</option><option value="image">Image</option><option value="video">Direct video</option><option value="youtube">YouTube</option><option value="vimeo">Vimeo</option></select></div><div class="field"><label>URL</label><input id="mediaUrl" placeholder="https://..."></div><div class="field wide"><label>Caption</label><input id="mediaCaption" placeholder="What this media shows"></div></div><button class="solid-button" id="addTopicMedia" style="margin-top:12px">Add to this entry</button><div class="media-help">Supports image URLs, MP4/WebM/Ogg, YouTube, and Vimeo. Arbitrary visitor media stays local unless you build a moderated upload layer later.</div></div></section>
<section class="topic-section" id="sources"><div class="kicker">Reference desk</div><h2>Continue the research</h2><p>Babel points outward to source discovery rather than presenting a generated index as the final authority.</p><div class="source-list">${sources.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(x.name)}</b><span>${esc(x.note||'Open source')}</span></a>`).join('')}</div></section></article>
<aside class="topic-aside"><div class="side-title">Connected branches</div><div class="branch-list">${(topic.related||[]).map(x=>`<a href="/topic/${esc(slug(x))}" data-related="${esc(x)}">${esc(titleFromSlug(x))}<span>↗</span></a>`).join('')}</div><div style="height:30px"></div><div class="side-title">Tools</div><div class="side-list"><a href="/workbench?topic=${encodeURIComponent(topic.slug)}" data-route>Open in Workbench</a><a href="/network?focus=${encodeURIComponent(topic.slug)}" data-route>Show in Network</a><button id="copyTopic">Copy stable address</button></div></aside></div></div>`;
wireRoutes();document.querySelectorAll('[data-related]').forEach(a=>a.onclick=e=>{e.preventDefault();openTopic(a.dataset.related)});document.querySelector('#copyTopic').onclick=async()=>{await navigator.clipboard.writeText(location.href);toast('Topic address copied')};document.querySelector('#addTopicMedia').onclick=()=>{const url=document.querySelector('#mediaUrl').value.trim();if(!/^https?:\/\//i.test(url))return toast('Use an http or https media URL');const item={url,type:document.querySelector('#mediaType').value,caption:document.querySelector('#mediaCaption').value.trim()||'Attached media',addedAt:new Date().toISOString()};saveTopicMedia(topic.slug,item);toast('Media added to this browser');topicPage(topic.slug)}}
async function network(){setTitle('Network of Babel');await loadExplore();const topics=allTopics();const focus=new URLSearchParams(location.search).get('focus')||'';app.innerHTML=`<div class="page"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">Core system 01</div><h1>Network<br>of Babel</h1></div><p>Website Of Babel's own living knowledge graph. Each node is an indexed topic, each line a relationship. Search, pan, zoom, inspect, and open branches directly from the map.</p></div></header><div class="network-toolbar"><div class="left"><input class="network-search" id="netSearch" placeholder="Find a node"><button class="ghost-button" id="netFind">Find</button><button class="ghost-button" id="resetGraph">Reset view</button></div><div class="right"><small>${topics.length} visible nodes · drag to pan · wheel to zoom</small></div></div><div class="network-layout"><div><div class="network-box"><canvas id="netCanvas"></canvas></div><div class="legend"><span><i></i>Indexed topic</span><span><i style="background:var(--accent)"></i>Selected or foundation</span><span>Lines represent related-topic links or category bridges.</span></div></div><aside class="network-panel" id="netPanel"><div class="kicker">Network inspector</div><h3>Select a node</h3><p>Click any node to inspect it. Double-click or use the button here to open the full entry.</p></aside></div></div>`;drawNetwork(topics,focus)}
function drawNetwork(topics,focus=''){const canvas=document.querySelector('#netCanvas');if(!canvas)return;const box=canvas.parentElement,ctx=canvas.getContext('2d');let w=0,h=0,dpr=1,offset={x:0,y:0},zoom=1,drag=null,selected=null;const items=topics.slice(0,90);const nodes=items.map((t,i)=>{const a=i*2.399963229728653;const rr=50+7.5*Math.sqrt(i)*5;return{t,x:Math.cos(a)*rr,y:Math.sin(a)*rr,r:i<28?7:5,vx:0,vy:0}});const map=new Map(nodes.map(n=>[n.t.slug,n]));const edges=[];for(const n of nodes){for(const r of n.t.related||[]){const m=map.get(slug(r));if(m&&n!==m&&!edges.some(e=>(e[0]===n&&e[1]===m)||(e[0]===m&&e[1]===n)))edges.push([n,m])}}
const categories=new Map();nodes.forEach(n=>{if(!categories.has(n.t.category))categories.set(n.t.category,[]);categories.get(n.t.category).push(n)});for(const arr of categories.values())for(let i=1;i<arr.length;i+=3)edges.push([arr[i-1],arr[i]]);
for(let iter=0;iter<85;iter++){for(const n of nodes){n.vx*=.75;n.vy*=.75}for(let i=0;i<nodes.length;i++){for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j],dx=a.x-b.x,dy=a.y-b.y,d2=dx*dx+dy*dy+30,force=2400/d2,dist=Math.sqrt(d2);a.vx+=dx/dist*force;b.vx-=dx/dist*force;a.vy+=dy/dist*force;b.vy-=dy/dist*force}}for(const [a,b] of edges){const dx=b.x-a.x,dy=b.y-a.y,dist=Math.hypot(dx,dy)||1,delta=(dist-115)*.003;a.vx+=dx*delta;b.vx-=dx*delta;a.vy+=dy*delta;b.vy-=dy*delta}for(const n of nodes){n.vx+=-n.x*.0007;n.vy+=-n.y*.0007;n.x+=n.vx;n.y+=n.vy}}
function setup(){dpr=window.devicePixelRatio||1;w=box.clientWidth;h=box.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);paint()}
function palette(){const cs=getComputedStyle(document.documentElement);return{ink:cs.getPropertyValue('--ink').trim(),muted:cs.getPropertyValue('--muted').trim(),line:cs.getPropertyValue('--line').trim(),accent:cs.getPropertyValue('--accent').trim(),paper:cs.getPropertyValue('--paper').trim()}}
function paint(){const c=palette();ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2+offset.x,h/2+offset.y);ctx.scale(zoom,zoom);ctx.strokeStyle=c.line;ctx.lineWidth=1/zoom;ctx.globalAlpha=.8;for(const[a,b]of edges){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}ctx.globalAlpha=1;for(const n of nodes){const sel=n===selected||n.t.slug===focus;ctx.beginPath();ctx.arc(n.x,n.y,sel?n.r+3:n.r,0,Math.PI*2);ctx.fillStyle=sel?c.accent:c.ink;ctx.fill();if(zoom>.72&&(sel||n.r>=7)){ctx.fillStyle=sel?c.accent:c.muted;ctx.font=`${11/zoom}px ui-sans-serif`;ctx.fillText(n.t.title,n.x+(n.r+7)/zoom,n.y+4/zoom)}}ctx.restore()}
function screenToGraph(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left-w/2-offset.x)/zoom,y:(e.clientY-r.top-h/2-offset.y)/zoom}}
function select(n){selected=n;paint();const p=document.querySelector('#netPanel');p.innerHTML=`<div class="kicker">${esc(n.t.category||'General')}</div><h3>${esc(n.t.title)}</h3><p>${esc(n.t.dek||'Babel index entry.')}</p><div class="label-row"><span class="evidence-label"><i></i>${esc(n.t.evidence||'Open research')}</span></div><p><strong>${(n.t.related||[]).length}</strong> explicit branches</p><button class="solid-button" id="openNetTopic">Open entry</button>`;document.querySelector('#openNetTopic').onclick=()=>openTopic(n.t.slug)}
canvas.onpointerdown=e=>{const p=screenToGraph(e);const hit=nodes.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<(n.r+8)/zoom);drag={sx:e.clientX,sy:e.clientY,ox:offset.x,oy:offset.y,hit,moved:false};canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.sx,dy=e.clientY-drag.sy;if(Math.hypot(dx,dy)>4)drag.moved=true;if(!drag.hit||drag.moved){offset.x=drag.ox+dx;offset.y=drag.oy+dy;paint()}};canvas.onpointerup=()=>{if(drag?.hit&&!drag.moved)select(drag.hit);drag=null};canvas.ondblclick=e=>{const p=screenToGraph(e);const hit=nodes.find(n=>Math.hypot(n.x-p.x,n.y-p.y)<(n.r+9)/zoom);if(hit)openTopic(hit.t.slug)};canvas.onwheel=e=>{e.preventDefault();const factor=e.deltaY>0?.9:1.1;zoom=Math.max(.35,Math.min(2.6,zoom*factor));paint()};document.querySelector('#resetGraph').onclick=()=>{offset={x:0,y:0};zoom=1;selected=null;paint()};document.querySelector('#netFind').onclick=()=>{const q=document.querySelector('#netSearch').value.trim().toLowerCase();if(!q)return;const n=nodes.find(n=>n.t.title.toLowerCase().includes(q)||n.t.slug.includes(slug(q)));if(!n)return toast('No visible node matched');selected=n;offset={x:-n.x*zoom,y:-n.y*zoom};select(n)};document.querySelector('#netSearch').onkeydown=e=>{if(e.key==='Enter')document.querySelector('#netFind').click()};window.addEventListener('resize',setup,{once:true});setup();if(focus&&map.get(focus)){selected=map.get(focus);setTimeout(()=>select(selected),10)}}
function libraryAddress(seed){return `B-${hashHex(seed)}-${hashHex(String(seed).split('').reverse().join(''))}-${(hash32(seed+'room')%9999).toString().padStart(4,'0')}`}
function makeLibraryText(address,page=1,needle=''){const alphabet='abcdefghijklmnopqrstuvwxyz     ,.;:\'?-';const rnd=mulberry32(hash32(`${address}|${page}`));let chars=[];for(let i=0;i<4300;i++)chars.push(alphabet[Math.floor(rnd()*alphabet.length)]);let text=chars.join('');if(needle){const clean=String(needle).slice(0,260).toLowerCase();const at=120+Math.floor(rnd()*Math.max(1,text.length-clean.length-240));text=text.slice(0,at)+clean+text.slice(at+clean.length)}return text.replace(/(.{92})/g,'$1\n')}
function library(){setTitle('Library of Babel');const params=new URLSearchParams(location.search);const find=params.get('find')||'';const address=(params.get('address')||libraryAddress(find||'entrance')).slice(0,120);const page=Math.max(1,Math.min(9999,Number(params.get('page')||1)));const text=makeLibraryText(address,page,find);const rendered=esc(text);const highlighted=find?rendered.replace(new RegExp(escRegex(esc(find.toLowerCase())),'i'),m=>`<mark>${m}</mark>`):rendered;app.innerHTML=`<div class="page"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">Core system 02</div><h1>Library<br>of Babel</h1></div><p>Website Of Babel's own deterministic library. Addresses generate repeatable pages. Phrase search maps a phrase into a reproducible coordinate and places it inside that generated page so the same query returns to the same room.</p></div></header><div class="library-workspace"><aside class="library-controls"><div class="kicker">Locate</div><h3>Find a phrase</h3><p>This is a computational indexing system, not a claim that the text was physically stored before you searched it.</p><form id="phraseForm"><input class="library-input" id="phraseInput" placeholder="A phrase, sentence, name..." value="${esc(find)}" maxlength="260"><button class="solid-button">Locate phrase</button></form><div class="kicker">Open coordinate</div><h3>Address</h3><form id="addressForm"><input class="library-input" id="addressInput" value="${esc(address)}" maxlength="120"><button class="ghost-button">Open address</button></form><div class="coordinate-box">${esc(address)} / page ${page}</div><button class="ghost-button" id="copyLibrary" style="margin-top:9px">Copy coordinate</button><button class="ghost-button" id="randomLibrary" style="margin-top:9px">Random room</button><div class="kicker" style="margin-top:28px">Shelf map</div><div class="library-map">${Array.from({length:24},(_,i)=>`<button class="book-spine ${i+1===page?'active':''}" data-book-page="${i+1}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div></aside><main><div class="library-page"><div class="library-address">${esc(address)} · volume ${1+(hash32(address)%32)} · page ${page}</div><div class="library-text">${highlighted}</div></div><div class="library-pagination"><button class="ghost-button" id="prevPage">← Previous page</button><button class="ghost-button" id="nextPage">Next page →</button></div></main></div></div>`;
document.querySelector('#phraseForm').onsubmit=e=>{e.preventDefault();const q=document.querySelector('#phraseInput').value.trim();if(!q)return;route(`/library?find=${encodeURIComponent(q)}&address=${encodeURIComponent(libraryAddress(q))}&page=1`)};document.querySelector('#addressForm').onsubmit=e=>{e.preventDefault();const a=document.querySelector('#addressInput').value.trim();if(!a)return;route(`/library?address=${encodeURIComponent(a)}&page=1`)};document.querySelector('#copyLibrary').onclick=async()=>{const c=`babel://library/${address}/page/${page}${find?`?find=${encodeURIComponent(find)}`:''}`;await navigator.clipboard.writeText(c);toast('Library coordinate copied')};document.querySelector('#randomLibrary').onclick=()=>{const seed=crypto.getRandomValues(new Uint32Array(2)).join('-');route(`/library?address=${encodeURIComponent(libraryAddress(seed))}&page=1`)};document.querySelector('#prevPage').onclick=()=>route(`/library?${find?`find=${encodeURIComponent(find)}&`:''}address=${encodeURIComponent(address)}&page=${Math.max(1,page-1)}`);document.querySelector('#nextPage').onclick=()=>route(`/library?${find?`find=${encodeURIComponent(find)}&`:''}address=${encodeURIComponent(address)}&page=${page+1}`);document.querySelectorAll('[data-book-page]').forEach(b=>b.onclick=()=>route(`/library?${find?`find=${encodeURIComponent(find)}&`:''}address=${encodeURIComponent(address)}&page=${b.dataset.bookPage}`))}
function escRegex(s){return String(s).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
async function piPage(){
  setTitle('Pi of Babel');
  const meta=await fetch('/data/math-constants.json').then(r=>r.json()).catch(()=>({pi:{digits:1000000,sha256:'unknown'}}));
  if(!state.piDigits){start();try{const r=await fetch('/data/pi-1m.txt');if(!r.ok)throw new Error('pi corpus unavailable');state.piDigits=(await r.text()).replace(/\D/g,'')}catch{state.piDigits='314159265358979323846264338327950288419716939937510'}finally{stop()}}
  const digits=state.piDigits.trim();
  const params=new URLSearchParams(location.search);
  const find=(params.get('find')||'').replace(/\D/g,'').slice(0,500);
  const requested=Math.max(1,Math.min(digits.length,Number(params.get('at')||1)||1));
  const hitCap=100;
  const hits=find?findOccurrences(digits,find,hitCap):[];
  const center=hits.length?hits[0]:requested-1;
  const windowStart=Math.max(0,center-500);
  const windowSize=5000;
  const excerpt=digits.slice(windowStart,windowStart+windowSize);
  const marked=find?esc(excerpt).replace(new RegExp(escRegex(find),'g'),m=>`<mark>${m}</mark>`):esc(excerpt);
  const freq=Array.from({length:10},(_,d)=>[d,0]);for(let i=0;i<digits.length;i++)freq[digits.charCodeAt(i)-48][1]++;
  const countOccurrences=q=>{if(!q)return 0;let n=0,pos=0;while((pos=digits.indexOf(q,pos))!==-1){n++;pos+=Math.max(1,q.length);if(n>=1000000)break}return n};
  const totalHits=find?countOccurrences(find):0;
  const expectedHash=meta.pi?.sha256||'unknown';
  let runtimeHash='unavailable';
  try{const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(digits));runtimeHash=[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('')}catch{}
  const verified=runtimeHash===expectedHash;
  const runInfo=(()=>{let best={digit:'',len:0,start:0},cur='',len=0,start=0;for(let i=0;i<digits.length;i++){if(digits[i]===cur)len++;else{cur=digits[i];len=1;start=i}if(len>best.len)best={digit:cur,len,start}}return best})();
  app.innerHTML=`<div class="page pi-v4"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">NUMERIC ARCHIVE · VERIFIED CORPUS</div><h1>Pi<br>of Babel</h1></div><p>Search the first <strong>${digits.length.toLocaleString()} computed digits of π</strong>. Results are literal positions in the bundled corpus, never invented matches. A corpus hash is shown so the dataset can be audited.</p></div></header>
  <section class="pi-proof-strip"><div><span>Corpus</span><strong>${digits.length.toLocaleString()} digits</strong></div><div><span>SHA-256</span><strong class="mono-wrap">${esc(expectedHash.slice(0,20))}…</strong></div><div><span>Runtime check</span><strong>${verified?'VERIFIED':'CHECK DATASET'}</strong></div><div><span>Longest repeated digit</span><strong>${runInfo.digit} × ${runInfo.len} @ ${runInfo.start+1}</strong></div></section>
  <div class="pi-layout"><main class="pi-main">
    <div class="pi-tools-v4"><form class="pi-search" id="piSearch"><input class="pi-input" id="piInput" inputmode="numeric" placeholder="Search digits: 314159, birthday, sequence..." value="${esc(find)}" maxlength="500"><button class="solid-button">Search 1,000,000 digits</button></form><form class="pi-jump" id="piJump"><input id="piPosition" type="number" min="1" max="${digits.length}" value="${requested}" placeholder="Position"><button>Jump to position</button></form></div>
    <div class="digit-window-meta"><span>Showing positions ${(windowStart+1).toLocaleString()}–${Math.min(digits.length,windowStart+windowSize).toLocaleString()}</span><button id="copyPiAddress">Copy π:${String(center+1).padStart(7,'0')}</button></div>
    <div class="digit-stream" id="digitStream">${marked}</div>
    <div class="pi-results">${find?`<div class="section-row" style="margin:30px 0 10px"><div><div class="kicker">EXACT SEARCH RESULTS</div><h2>${totalHits.toLocaleString()} occurrence${totalHits===1?'':'s'} in this corpus</h2></div></div>${hits.length?hits.map((pos,i)=>`<div class="pi-hit" data-pi-pos="${pos}"><strong>π:${String(pos+1).padStart(7,'0')} ${i===0?'· first occurrence':''}</strong><div>${esc(digits.slice(Math.max(0,pos-28),pos))}[${esc(digits.slice(pos,pos+find.length))}]${esc(digits.slice(pos+find.length,pos+find.length+28))}</div></div>`).join(''):'<div class="banner">That sequence does not occur in the bundled one-million-digit corpus. That says nothing about digits beyond this corpus.</div>'}`:`<div class="banner"><strong>No fake Pi oracle.</strong> Enter a decimal sequence or jump to a position. Every match shown is found directly in the bundled digits.</div>`}</div>
  </main><aside><div class="pi-panel"><div class="kicker">DIGIT FIELD</div><h3>First 4,096 digits</h3><canvas class="pi-canvas" id="piCanvas" width="512" height="512"></canvas><div class="freq">${freq.map(([d,n])=>`<div><strong>${d}</strong><span>${n.toLocaleString()}</span></div>`).join('')}</div></div><div class="pi-panel" style="margin-top:16px"><div class="kicker">WORD → DIGIT SIGNATURE</div><h3>Find an explicit encoding in π</h3><p class="muted">Text is converted to decimal UTF-8 bytes. If those digits occur in π, Babel reports the literal location. A match is numerical coincidence, not hidden semantic meaning.</p><div class="media-form-row"><input id="sigInput" placeholder="Any word or phrase"><button class="ghost-button" id="makeSig">Encode</button></div><div class="coordinate-box" id="sigOut" style="margin-top:10px">No signature yet.</div></div></aside></div></div>`;
  drawPiCanvas();
  document.querySelector('#piSearch').onsubmit=e=>{e.preventDefault();const q=document.querySelector('#piInput').value.replace(/\D/g,'').slice(0,500);route(`/pi${q?`?find=${encodeURIComponent(q)}`:''}`)};
  document.querySelector('#piJump').onsubmit=e=>{e.preventDefault();const at=Math.max(1,Math.min(digits.length,Number(document.querySelector('#piPosition').value)||1));route(`/pi?at=${at}`)};
  document.querySelector('#copyPiAddress').onclick=()=>copyText(`π:${String(center+1).padStart(7,'0')}`);
  document.querySelectorAll('[data-pi-pos]').forEach(el=>el.onclick=()=>{const pos=Number(el.dataset.piPos);route(`/pi?find=${encodeURIComponent(find)}&at=${pos+1}`)});
  document.querySelector('#makeSig').onclick=()=>{const t=document.querySelector('#sigInput').value;const sig=textSignature(t);const out=document.querySelector('#sigOut');out.innerHTML=sig?`<strong>${esc(sig)}</strong><br>${sig.length} digits`:'No signature yet.';if(sig){const btn=document.createElement('button');btn.className='ghost-button';btn.style.marginTop='8px';btn.textContent='Search signature in π';btn.onclick=()=>route(`/pi?find=${encodeURIComponent(sig)}`);out.after(btn)}};
}
function findOccurrences(hay,needle,limit=50){const out=[];if(!needle)return out;let at=0;while(out.length<limit){const i=hay.indexOf(needle,at);if(i<0)break;out.push(i);at=i+1}return out}
function textSignature(text){if(!text)return'';const bytes=new TextEncoder().encode(text);return Array.from(bytes).map(b=>String(b).padStart(3,'0')).join('').slice(0,500)}
function drawPiCanvas(){const canvas=document.querySelector('#piCanvas');if(!canvas||!state.piDigits)return;const ctx=canvas.getContext('2d');const digits=state.piDigits.slice(0,4096);const size=64,cell=canvas.width/size;const dark=document.documentElement.dataset.theme==='dark';for(let i=0;i<digits.length;i++){const d=Number(digits[i]);const hue=(d*31+145)%360;ctx.fillStyle=`hsl(${hue} ${dark?38:48}% ${dark?38:48}%)`;ctx.fillRect((i%size)*cell,Math.floor(i/size)*cell,cell+.5,cell+.5)}}
function drawBabelImage(seed){const canvas=document.querySelector('#imageCanvas');if(!canvas)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,rnd=mulberry32(hash32(seed||'babel'));const cells=24,cell=w/cells,baseHue=Math.floor(rnd()*360);ctx.fillStyle='#0b0d0b';ctx.fillRect(0,0,w,h);for(let y=0;y<cells;y++){for(let x=0;x<Math.ceil(cells/2);x++){const on=rnd()>.43;const hue=(baseHue+Math.floor(rnd()*90)-45+360)%360;const sat=35+Math.floor(rnd()*50),light=25+Math.floor(rnd()*50);ctx.fillStyle=on?`hsl(${hue} ${sat}% ${light}%)`:'hsl(0 0% 6%)';ctx.fillRect(x*cell,y*cell,cell+1,cell+1);ctx.fillRect((cells-1-x)*cell,y*cell,cell+1,cell+1)}}}
function mediaPage(){setTitle('Media');const saved=roomMedia();app.innerHTML=`<div class="page"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">Generative + linked media</div><h1>Media</h1></div><p>Images and video are first-class objects in Babel. Generate deterministic Images of Babel, preview remote media, save a personal shelf, and attach media to knowledge entries.</p></div></header><div class="media-lab"><section class="lab-card"><div class="kicker">Images of Babel</div><h2>Seeded image room</h2><p>The same seed always generates the same mirrored pixel field in this browser. No external image model is required.</p><div class="media-form-row"><input id="imageSeed" value="website of babel" placeholder="Image seed"><button class="ghost-button" id="generateImage">Generate</button></div><div class="image-canvas-wrap"><canvas id="imageCanvas" width="720" height="720"></canvas></div><div class="media-form-row"><button class="solid-button" id="downloadImage">Save PNG</button><button class="ghost-button" id="randomImage">Random seed</button></div></section><section class="lab-card"><div class="kicker">Video + image preview</div><h2>Media viewer</h2><p>Paste an image, MP4/WebM/Ogg, YouTube, or Vimeo URL. You can save the reference to your local Media shelf.</p><div class="media-form-row"><input id="previewUrl" placeholder="https://..."><button class="ghost-button" id="previewMedia">Preview</button></div><div class="video-preview" id="videoPreview">Paste a media URL above.</div><div class="media-form-row"><input id="previewCaption" placeholder="Caption"><button class="solid-button" id="saveMedia">Save to shelf</button></div></section></div><div class="section-row"><div><div class="kicker">Personal shelf</div><h2>Saved media</h2></div><p>Saved references live in this browser. Topic-specific media is stored separately with each entry.</p></div><div class="saved-media" id="savedMedia">${saved.length?saved.map(mediaHTML).join(''):'<div class="banner">Your media shelf is empty.</div>'}</div></div>`;
drawBabelImage('website of babel');document.querySelector('#generateImage').onclick=()=>drawBabelImage(document.querySelector('#imageSeed').value.trim()||'babel');document.querySelector('#randomImage').onclick=()=>{const v=crypto.getRandomValues(new Uint32Array(2)).join('-');document.querySelector('#imageSeed').value=v;drawBabelImage(v)};document.querySelector('#downloadImage').onclick=()=>{const a=document.createElement('a');a.download=`babel-image-${slug(document.querySelector('#imageSeed').value)}.png`;a.href=document.querySelector('#imageCanvas').toDataURL('image/png');a.click()};const renderPreview=()=>{const url=document.querySelector('#previewUrl').value.trim();if(!/^https?:\/\//i.test(url))return toast('Use an http or https URL');document.querySelector('#videoPreview').innerHTML=mediaHTML({url,caption:'Preview'}).replace(/^<div class="media-item"><div class="media-frame">|<\/div><div class="media-caption">[\s\S]*$/g,'')};document.querySelector('#previewMedia').onclick=renderPreview;document.querySelector('#saveMedia').onclick=()=>{const url=document.querySelector('#previewUrl').value.trim();if(!/^https?:\/\//i.test(url))return toast('Preview a valid URL first');saveRoomMedia({url,caption:document.querySelector('#previewCaption').value.trim()||'Saved media',type:'auto',addedAt:new Date().toISOString()});toast('Saved to media shelf');mediaPage()}}
function workbench(){setTitle('Workbench');const params=new URLSearchParams(location.search);const s=params.get('topic');const t=allTopics().find(x=>x.slug===s)||localTopics()[s]||state.current;const subject=t?.title||'a subject from the index';app.innerHTML=`<div class="page"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">Transform knowledge</div><h1>Workbench</h1></div><p>Choose a structure. Workbench turns the current entry into something you can study, remember, compare, investigate, or build.</p></div></header><div class="workbench-grid"><aside class="work-tools"><button class="active" data-tool="lesson">Lesson</button><button data-tool="palace">Memory route</button><button data-tool="timeline">Timeline</button><button data-tool="project">Project brief</button><button data-tool="questions">Research questions</button><button data-tool="compare">Compare claims</button></aside><div class="work-output"><div class="kicker">Current subject</div><h2>${esc(subject)}</h2><div class="worksheet" id="worksheet"></div></div></div></div>`;const rel=(t?.related||['foundations','history','evidence','applications']).slice(0,6).map(titleFromSlug);const render=tool=>{const title=esc(subject);const templates={lesson:`<h3>A compact lesson on ${title}</h3><ol><li>Write a one-sentence definition without jargon.</li><li>Learn the five most important terms.</li><li>Study one concrete example or demonstration.</li><li>Separate the strongest established claim from weaker or speculative claims.</li><li>Retrieve the explanation without notes.</li><li>Follow one connected branch and explain how it changes the picture.</li></ol><p><strong>Branches:</strong> ${rel.map(esc).join(' · ')}</p>`,palace:`<h3>Memory route: ${title}</h3><ol><li><strong>Door:</strong> definition and scope.</li><li><strong>Hall:</strong> core vocabulary.</li><li><strong>Table:</strong> three mechanisms or central ideas.</li><li><strong>Window:</strong> strongest evidence or worked example.</li><li><strong>Stairs:</strong> objections, limitations, and uncertainty.</li><li><strong>Exit:</strong> related branches to revisit later.</li></ol>`,timeline:`<h3>Timeline skeleton: ${title}</h3><ul><li>Origins or earliest relevant records</li><li>Major conceptual shift</li><li>Important experiment, text, implementation, or discovery</li><li>Modern understanding</li><li>Current disputes and open questions</li></ul>`,project:`<h3>Project brief: ${title}</h3><p><strong>Goal:</strong> create a small artifact that demonstrates one important idea from the subject.</p><ul><li>Choose one narrow question.</li><li>Collect at least three credible sources.</li><li>Build a diagram, simulation, code demo, physical model, dataset, or annotated explanation.</li><li>Record assumptions and what the artifact leaves out.</li><li>Publish a concise conclusion with links back to evidence.</li></ul>`,questions:`<h3>Research questions for ${title}</h3><ul><li>How is the term defined across fields or traditions?</li><li>Which claims are strongly supported, and by what kind of evidence?</li><li>Which claims are disputed, untested, or speculative?</li><li>What observation would count against the strongest claim?</li><li>Which primary sources matter most?</li><li>What practical skill or experiment can test part of the topic?</li></ul>`,compare:`<h3>Claim comparison: ${title}</h3><table style="width:100%;border-collapse:collapse"><tr><th style="text-align:left;border-bottom:1px solid var(--line);padding:8px">Claim</th><th style="text-align:left;border-bottom:1px solid var(--line);padding:8px">Evidence</th><th style="text-align:left;border-bottom:1px solid var(--line);padding:8px">What would change confidence?</th></tr><tr><td style="padding:8px">Most established claim</td><td style="padding:8px">Primary data, formal proof, replication, or strong consensus</td><td style="padding:8px">Contradictory high-quality evidence</td></tr><tr><td style="padding:8px">Open or disputed claim</td><td style="padding:8px">Mixed evidence or unresolved theory</td><td style="padding:8px">Better measurements or clearer predictions</td></tr><tr><td style="padding:8px">Speculative claim</td><td style="padding:8px">Possibility, analogy, or tradition</td><td style="padding:8px">Direct testable evidence</td></tr></table>`};document.querySelector('#worksheet').innerHTML=templates[tool]};document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tool]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(b.dataset.tool)});render('lesson')}
function about(){setTitle('About');app.innerHTML=`<div class="page"><header class="page-head"><div class="page-head-grid"><div><div class="kicker">Architecture + principles</div><h1>About</h1></div><p>Website Of Babel is a self-expanding knowledge index and collection of deterministic exploration systems designed to deploy cleanly from GitHub to Vercel.</p></div></header><div class="principle-grid"><section class="principle"><div class="kicker">01</div><h2>Our own Babel systems</h2><p>The internal Network, Library, Pi archive, and Images room are implemented by this project. They do not embed or impersonate similarly named independent sites.</p></section><section class="principle"><div class="kicker">02</div><h2>Stable code, growing knowledge</h2><p>The application code stays reviewable in GitHub. What expands through use is the indexed knowledge layer, local media layer, and shared topic store when Redis is configured.</p></section><section class="principle"><div class="kicker">03</div><h2>Evidence remains visible</h2><p>Physics can sit beside folklore and practical skills can sit beside esoteric history, but the labels keep those categories from silently becoming equivalent claims.</p></section><section class="principle"><div class="kicker">04</div><h2>Generated does not mean discovered</h2><p>The Library and Images rooms use deterministic generation. A phrase mapped into a generated library page is an index operation, not evidence that a physical universal library contains that phrase somewhere.</p></section><section class="principle"><div class="kicker">05</div><h2>External inspirations</h2><p>libraryofbabel.info and networkofbabel.com remain independent projects. This project can link to them as inspirations while maintaining its own implementation, identity, and data.</p><p><a class="section-link" href="https://libraryofbabel.info/" target="_blank" rel="noopener noreferrer">libraryofbabel.info ↗</a><br><br><a class="section-link" href="https://networkofbabel.com/" target="_blank" rel="noopener noreferrer">networkofbabel.com ↗</a></p></section><section class="principle"><div class="kicker">06</div><h2>Vercel persistence</h2><p>Without a database the app still works and browser-created entries persist locally. Add Upstash Redis environment variables to share created topic entries across visitors.</p></section></div></div>`}
function notFound(){setTitle('Not found');app.innerHTML=`<div class="page"><div class="empty">That room does not exist. <a href="/" data-route style="border-bottom:1px solid">Return to the index.</a></div></div>`;wireRoutes()}
async function renderRoute(){window.scrollTo(0,0);document.querySelectorAll('.nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===location.pathname));const p=location.pathname;if(p==='/')return home();if(p==='/explore')return explore();if(p==='/network')return network();if(p==='/library')return library();if(p==='/pi')return piPage();if(p==='/media')return mediaPage();if(p==='/workbench')return workbench();if(p==='/about')return about();if(p.startsWith('/topic/'))return topicPage(decodeURIComponent(p.split('/')[2]||''));return notFound()}
window.onpopstate=renderRoute;document.querySelector('#mobileNav').onclick=()=>nav.classList.toggle('open');initTheme();loadExplore().then(()=>loadStats()).finally(()=>renderRoute());
